cat /home/ubuntu/.claude-account-3/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-9-projects-event-gated-adaptive-horizon/ae813a79-db9f-4a12-b6ee-ad91ade39065/tool-results/mcp-agent-ml-research-read_registry-1779718348946.txt | python3 -c "
import json, sys
data = json.load(sys.stdin)
result = json.loads(data['result'])
exps = result.get('data', result)
if isinstance(exps, dict) and 'experiments' in exps:
    exps = exps['experiments']
elif isinstance(exps, dict) and 'data' in exps:
    exps = exps['data']

if isinstance(exps, dict):
    items = exps
else:
    items = {str(i): e for i, e in enumerate(exps)}

# Count by status
status_counts = {}
for eid, e in items.items():
    s = e.get('status', 'unknown')
    status_counts[s] = status_counts.get(s, 0) + 1

print('Status counts:')
for k, v in sorted(status_counts.items()):
    print(f'  {k}: {v}')

# Count experiments excluding RUNNING/unknown status ones (i.e., completed experiments)
completed_statuses = {'DONE', 'RUNNING', 'PAUSED'}
concluded = {k: v for k, v in items.items() if isinstance(v, dict)}

# Check if there's an 'environment' or 'env' field
first_full = list(items.values())[0]
print(f'\\nAll keys in first full record: {sorted(first_full.keys())}')

# Look at a few experiments' tags or config
for eid in ['exp_008d', 'exp_042_frozen_dt_emb_walker', 'exp_050_peginsertion_civo_trigger_s0']:
    if eid in items:
        e = items[eid]
        print(f'\\n{eid}:')
        for k in ['tags', 'config', 'environment', 'env', 'env_id', 'method', 'intervention']:
            if k in e:
                print(f'  {k}: {e[k]}')
"

